package com.training.accounting.auth; import com.training.accounting.user.AppUser; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.time.Instant; import java.util.Date;
@Service public class JwtService { private final SecretKey key; private final long mins; public JwtService(@Value("${app.jwt.secret}") String s,@Value("${app.jwt.expiration-minutes}") long m){key=Keys.hmacShaKeyFor(s.getBytes(StandardCharsets.UTF_8));mins=m;} public String createToken(AppUser u){Instant n=Instant.now();return Jwts.builder().subject(u.getEmail()).claim("uid",u.getId()).claim("businessId",u.getBusinessId()).claim("role",u.getRole()).issuedAt(Date.from(n)).expiration(Date.from(n.plusSeconds(mins*60))).signWith(key).compact();} public Claims parse(String t){return Jwts.parser().verifyWith(key).build().parseSignedClaims(t).getPayload();} }
